///Claims of the Ed25519 access JWT issued by the backend and checked by media-server.
class AccessTokenClaims {
  final String clientId;
  final int exp;
  final int iat;
  final TokenLicenseStatus lic;
  final Role role;

  ///device_id for a camera, viewer_id for a viewer.
  final String sub;

  ///The camera's table, or the table a viewer asked for. A viewer token without it is good
  ///for the REST API only: media-server lets nobody into a room without it.
  final String? tableId;

  AccessTokenClaims({
    required this.clientId,
    required this.exp,
    required this.iat,
    required this.lic,
    required this.role,
    required this.sub,
    this.tableId,
  });

  factory AccessTokenClaims.fromJson(Map<String, dynamic> json) =>
      AccessTokenClaims(
        clientId: json["client_id"],
        exp: json["exp"],
        iat: json["iat"],
        lic: tokenLicenseStatusValues.map[json["lic"]]!,
        role: roleValues.map[json["role"]]!,
        sub: json["sub"],
        tableId: json["table_id"],
      );

  Map<String, dynamic> toJson() => {
    "client_id": clientId,
    "exp": exp,
    "iat": iat,
    "lic": tokenLicenseStatusValues.reverse[lic],
    "role": roleValues.reverse[role],
    "sub": sub,
    "table_id": tableId,
  };
}

enum TokenLicenseStatus { ACTIVE, GRACE }

final tokenLicenseStatusValues = EnumValues({
  "active": TokenLicenseStatus.ACTIVE,
  "grace": TokenLicenseStatus.GRACE,
});

enum Role { CAMERA, VIEWER }

final roleValues = EnumValues({"camera": Role.CAMERA, "viewer": Role.VIEWER});

///branding/<brand>/brand.json
class BrandConfig {
  final String androidApplicationId;
  final String appName;
  final BrandColors colors;

  ///File in the brand's folder, square, at least 1024x1024.
  final String icon;

  ///File in the brand's folder.
  final String logo;
  final String windowsAppId;

  BrandConfig({
    required this.androidApplicationId,
    required this.appName,
    required this.colors,
    required this.icon,
    required this.logo,
    required this.windowsAppId,
  });

  factory BrandConfig.fromJson(Map<String, dynamic> json) => BrandConfig(
    androidApplicationId: json["android_application_id"],
    appName: json["app_name"],
    colors: BrandColors.fromJson(json["colors"]),
    icon: json["icon"],
    logo: json["logo"],
    windowsAppId: json["windows_app_id"],
  );

  Map<String, dynamic> toJson() => {
    "android_application_id": androidApplicationId,
    "app_name": appName,
    "colors": colors.toJson(),
    "icon": icon,
    "logo": logo,
    "windows_app_id": windowsAppId,
  };
}

